import{c as n,Q as s,J as o,h as l,k as t,m as e,e as c}from"./chunks/framework.WgZQdPFo.js";const y=JSON.parse('{"title":"Pricing, Markup, and Margin: How to Never Sell at a Loss","description":"Practical pricing guide for small workshops and makers. Understand the difference between markup and margin, master retail pricing formulas, and use the cost calculator.","frontmatter":{"title":"Pricing, Markup, and Margin: How to Never Sell at a Loss","description":"Practical pricing guide for small workshops and makers. Understand the difference between markup and margin, master retail pricing formulas, and use the cost calculator.","tags":["Economics","Tools","Workshop"],"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Pricing, Markup, and Margin: How to Never Sell at a Loss"}],["meta",{"property":"og:description","content":"Practical pricing guide for small workshops and makers. Understand the difference between markup and margin, master retail pricing formulas, and use the cost calculator."}],["meta",{"property":"og:url","content":"https://omnicraft-erp.com/articles/pricing-and-margins"}],["meta",{"property":"og:image","content":"https://omnicraft-erp.com/img/en/front/calculator.webp"}],["script",{"type":"application/ld+json"},"{\\n  \\"@context\\": \\"https://schema.org\\",\\n  \\"@graph\\": [\\n    {\\n      \\"@type\\": \\"WebApplication\\",\\n      \\"name\\": \\"Online Markup & Margin Calculator\\",\\n      \\"applicationCategory\\": \\"BusinessApplication\\",\\n      \\"operatingSystem\\": \\"All\\",\\n      \\"browserRequirements\\": \\"Requires JavaScript. Requires HTML5.\\",\\n      \\"offers\\": {\\n        \\"@type\\": \\"Offer\\",\\n        \\"price\\": \\"0\\",\\n        \\"priceCurrency\\": \\"USD\\"\\n      },\\n      \\"description\\": \\"Interactive online retail markup and gross profit margin calculator for handcrafted goods, small workshops, and custom production.\\"\\n    },\\n    {\\n      \\"@type\\": \\"Article\\",\\n      \\"headline\\": \\"Pricing, Markup, and Margin: How to Never Sell at a Loss\\",\\n      \\"description\\": \\"Practical pricing guide for small workshops and makers. Understand the difference between markup and margin, master retail pricing formulas, and use the cost calculator.\\",\\n      \\"image\\": \\"https://omnicraft-erp.com/img/en/front/calculator.webp\\",\\n      \\"inLanguage\\": \\"en-US\\",\\n      \\"mainEntityOfPage\\": \\"https://omnicraft-erp.com/articles/pricing-and-margins\\",\\n      \\"datePublished\\": \\"2026-10-10\\",\\n      \\"dateModified\\": \\"2026-10-24\\",\\n      \\"author\\": {\\n        \\"@type\\": \\"Organization\\",\\n        \\"name\\": \\"OmniCraft ERP\\",\\n        \\"url\\": \\"https://omnicraft-erp.com/\\"\\n      },\\n      \\"publisher\\": {\\n        \\"@type\\": \\"Organization\\",\\n        \\"name\\": \\"OmniCraft ERP\\",\\n        \\"logo\\": {\\n          \\"@type\\": \\"ImageObject\\",\\n          \\"url\\": \\"https://omnicraft-erp.com/logo.svg\\"\\n        }\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"BreadcrumbList\\",\\n      \\"itemListElement\\": [\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 1,\\n          \\"name\\": \\"Home\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/\\"\\n        },\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 2,\\n          \\"name\\": \\"Guides & Articles\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/articles/\\"\\n        },\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 3,\\n          \\"name\\": \\"Pricing, Markup & Margins\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/articles/pricing-and-margins\\"\\n        }\\n      ]\\n    }\\n  ]\\n}\\n"]]},"headers":[],"relativePath":"articles/pricing-and-margins.md","filePath":"articles/pricing-and-margins.md"}'),p={name:"articles/pricing-and-margins.md"},d={class:"interactive-frame-container"};function m(u,a,h,g,f,v){const r=s("MarginCalculator"),i=s("OmniCraftFrame");return o(),l("div",null,[a[0]||(a[0]=t('<div class="article-breadcrumb"><a href="/articles/">← All Guides &amp; Articles</a></div><h1 id="pricing-markup-and-margin-how-to-never-sell-at-a-loss" tabindex="-1">Pricing, Markup, and Margin: How to Never Sell at a Loss <a class="header-anchor" href="#pricing-markup-and-margin-how-to-never-sell-at-a-loss" aria-label="Permalink to &quot;Pricing, Markup, and Margin: How to Never Sell at a Loss&quot;">​</a></h1><p>Confusing <strong>markup</strong> with <strong>gross profit margin</strong> is the single most common financial trap in craft manufacturing.</p><p>A maker calculates raw material costs for a leather wallet — totaling <strong>$30</strong>. Wanting a 40% profit, they add a 40% markup ($42). Later, they offer a 30% discount, assuming 10% profit remains. In reality, the discounted price is <strong>$29.40</strong>, causing the maker to lose $0.60 per sale while giving away their labor for free.</p>',4)),e(r,{lang:"en","default-cost":100}),a[1]||(a[1]=t('<hr><h2 id="markup-vs-margin-what-is-the-fundamental-difference" tabindex="-1">Markup vs. Margin: What Is the Fundamental Difference? <a class="header-anchor" href="#markup-vs-margin-what-is-the-fundamental-difference" aria-label="Permalink to &quot;Markup vs. Margin: What Is the Fundamental Difference?&quot;">​</a></h2><p>Many makers treat &quot;markup&quot; and &quot;margin&quot; as interchangeable synonyms. This common mistake leads straight into unexpected cash deficits.</p><div class="price-breakdown-card"><div class="breakdown-header"><span class="breakdown-tag">Retail Price Breakdown</span><div class="breakdown-title">Revenue Structure: Production Cost, Margin, and Markup</div><p class="breakdown-desc">With production cost at 60% of price and a 66.7% markup on cost, the final gross profit margin is exactly 40%:</p></div><div class="breakdown-bar-track"><div class="breakdown-segment seg-cost" style="width:60%;background:#64748b;" data-tooltip="Unit Cost: 60% of Revenue (100% Base)"><span class="seg-label">Unit Cost: 60% of Revenue (100% Base)</span></div><div class="breakdown-segment seg-margin" style="width:40%;background:#10b981;" data-tooltip="Gross Margin: 40% (66.7% Markup)"><span class="seg-label">Gross Margin: 40% (66.7% Markup)</span></div></div></div><div class="craft-metaphor-card"><div class="metaphor-header"><div class="metaphor-badge-row"><span class="metaphor-badge">Canonical Workshop Metaphor</span><span class="metaphor-badge-method">Core Studio Economics</span></div><div class="metaphor-title"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="metaphor-icon"><circle cx="12" cy="12" r="10"></circle><path d="M12 2a10 10 0 0 1 10 10H12V2z"></path></svg> &quot;The Revenue Pie vs. The Cost Foundation&quot;: Why Margin Can Never Exceed 100% </div></div><p class="metaphor-story"> Think of <strong>markup</strong> as an additional building floor erected on top of your <em>cost foundation</em>. If the foundation cost $100, you can add a $50 floor (50% markup), a $100 floor (100% markup), or even a $300 floor (300% markup). There is no upper ceiling. </p><p class="metaphor-story"><strong>Gross margin</strong>, by contrast, is a <em>slice of the baked revenue pie</em> handed to you by the paying customer. The total cash collected is 100% of the pie. The raw materials supplier immediately takes their slice (unit cost), and what remains on your plate is your gross margin. You physically cannot cut a slice larger than the whole pie: this is why margin <strong>can never exceed 100%</strong>. </p><div class="metaphor-math-grid"><div class="metaphor-math-step"><div class="step-label">Cost Foundation</div><div class="step-val">Unit Cost = <strong>$100</strong></div></div><div class="metaphor-math-op">+</div><div class="metaphor-math-step"><div class="step-label">Cost Markup (+100%)</div><div class="step-val">Added Markup = <strong>$100</strong></div></div><div class="metaphor-math-op">=</div><div class="metaphor-math-step highlight-step"><div class="step-label">Revenue Pie (Selling Price)</div><div class="step-val">$200 → Realized Margin = <strong>50%</strong></div></div></div><p class="metaphor-conclusion"> A 100% markup (doubling your production cost) yields exactly <strong>50% gross margin</strong>, not 100%. Confusing these two bases makes makers believe they have a 100% safety buffer, leading to immediate deficits during seasonal promotional sales. </p></div><h3 id="_1-retail-markup" tabindex="-1">1. Retail Markup <a class="header-anchor" href="#_1-retail-markup" aria-label="Permalink to &quot;1. Retail Markup&quot;">​</a></h3><p>Markup measures <strong>how much the retail price exceeds the production cost</strong>, expressed as a percentage of cost.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Markup Formula</span><div class="formula-heading">Retail Markup from Unit Cost (Markup %)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Markup %</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Selling Price</span> <span class="math-op">−</span> <span class="math-var">Unit Cost</span></span><span class="math-denom"><span class="math-var">Unit Cost</span></span></span><span class="math-op">×</span><span class="math-var">100%</span></div></div></div><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Limits:</strong> Markup can be 50%, 100%, 300%, or more — there is no upper ceiling. If a leather glasses sleeve costs $15 to produce and you sell it for $45, your markup is 200%.</div></li></ul><h3 id="_2-profit-margin" tabindex="-1">2. Profit Margin <a class="header-anchor" href="#_2-profit-margin" aria-label="Permalink to &quot;2. Profit Margin&quot;">​</a></h3><p>Margin measures <strong>what percentage of the final retail price represents gross profit</strong>, expressed as a percentage of revenue.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Margin Formula</span><div class="formula-heading">Gross Profit Margin from Retail Price (Margin %)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Margin %</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Selling Price</span> <span class="math-op">−</span> <span class="math-var">Unit Cost</span></span><span class="math-denom"><span class="math-var">Selling Price</span></span></span><span class="math-op">×</span><span class="math-var">100%</span></div></div></div><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Limits:</strong> Margin <strong>can never exceed 100%</strong>. Even if material cost is $0, selling an item for $50 yields an exact 100% margin.</div></li></ul><div class="tip custom-block"><p class="custom-block-title">Workshop Axiom: Margin Is Always Less Than Markup</p><p>For any identical dollar profit amount, margin percentage is <strong>always lower</strong> than markup percentage. A 50% markup produces 33.3% margin, a 100% markup yields exactly 50% margin, and a 300% markup yields only 75% margin.</p></div><h3 id="markup-vs-margin-conversion-reference-table" tabindex="-1">Markup vs. Margin Conversion Reference Table <a class="header-anchor" href="#markup-vs-margin-conversion-reference-table" aria-label="Permalink to &quot;Markup vs. Margin Conversion Reference Table&quot;">​</a></h3><table class="craft-matrix-table"><thead><tr><th style="width:20%;">Cost</th><th style="width:20%;">Target Margin</th><th style="width:20%;">Markup</th><th style="width:20%;">Retail Price</th><th style="width:20%;">Profit</th></tr></thead><tbody><tr><td>$100</td><td><strong>20%</strong></td><td><strong>25%</strong></td><td>$125</td><td>$25</td></tr><tr><td>$100</td><td><strong>30%</strong></td><td><strong>43%</strong></td><td>$143</td><td>$43</td></tr><tr><td>$100</td><td><strong>40%</strong></td><td><strong>67%</strong></td><td>$167</td><td>$67</td></tr><tr><td>$100</td><td><strong>50%</strong></td><td><strong>100%</strong></td><td>$200</td><td>$100</td></tr><tr><td>$100</td><td><strong>60%</strong></td><td><strong>150%</strong></td><td>$250</td><td>$150</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Beware the Blind Discount Trap</p><p>If you target a 40% sales margin, you must markup your production cost by <strong>67%, not 40%</strong>. Simply adding 40% leaves your realized gross margin at just 28.5%. A 30% customer discount applied to that price instantly drives your order into negative cash flow.</p></div><hr><h2 id="calculating-selling-price-from-cost-and-target-margin" tabindex="-1">Calculating Selling Price from Cost and Target Margin <a class="header-anchor" href="#calculating-selling-price-from-cost-and-target-margin" aria-label="Permalink to &quot;Calculating Selling Price from Cost and Target Margin&quot;">​</a></h2><p>When determining wholesale or retail prices, professional studios calculate forward from <strong>target margin</strong> rather than arbitrary markup percentages.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Pricing Formula</span><div class="formula-heading">Selling Price from Target Profit Margin</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Selling Price</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Total Unit Cost</span></span><span class="math-denom">1 <span class="math-op">−</span> <span class="math-fraction"><span class="math-num"><span class="math-var">Target Margin %</span></span><span class="math-denom">100</span></span></span></span></div></div></div><details class="details custom-block"><summary>Mathematical Derivation of the Target Margin Formula</summary><p>The pricing equation is derived directly from the fundamental margin definition:</p><ol class="craft-ordered-list"><li><span class="craft-step-num">1</span><div><strong>Definition:</strong> Margin = (Price − Cost) / Price</div></li><li><span class="craft-step-num">2</span><div><strong>Multiply both sides by Price:</strong> Price × Margin = Price − Cost</div></li><li><span class="craft-step-num">3</span><div><strong>Group terms:</strong> Cost = Price − (Price × Margin) = Price × (1 − Margin)</div></li><li><span class="craft-step-num">4</span><div><strong>Isolate selling price:</strong> Price = Cost / (1 − Margin)</div></li></ol></details><h4 id="workshop-example" tabindex="-1">Workshop Example: <a class="header-anchor" href="#workshop-example" aria-label="Permalink to &quot;Workshop Example:&quot;">​</a></h4><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div>Total production cost of a leather belt (bridle leather with scrap allowance + brass buckle + 2 hours craftsman labor + tool wear) = <strong>$45</strong>.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div>The workshop targets a <strong>35% gross margin</strong> (to cover studio rent, software, taxes, and expansion capital).</div></li></ul><div class="formula-hero-card" style="margin:16px 0;"><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Selling Price</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num">$45</span><span class="math-denom">1 <span class="math-op">−</span> 0.35</span></span><span class="math-op">=</span><span class="math-fraction"><span class="math-num">$45</span><span class="math-denom">0.65</span></span><span class="math-op">≈</span><span class="math-var" style="color:#10b981;">$69.23</span></div></div></div><p>Had the maker mistakenly added 35% directly to cost, the price would have been set at 45 × 1.35 = $60.75. That oversight leaks <strong>$8.48 in net profit</strong> on every single belt.</p><hr><h2 id="three-pricing-strategies-for-craft-workshops" tabindex="-1">Three Pricing Strategies for Craft Workshops <a class="header-anchor" href="#three-pricing-strategies-for-craft-workshops" aria-label="Permalink to &quot;Three Pricing Strategies for Craft Workshops&quot;">​</a></h2><p>In day-to-day manufacturing, studios generally utilize three core approaches to establish prices:</p><h3 id="_1-cost-plus-pricing-the-engineering-standard" tabindex="-1">1. Cost-Plus Pricing (The Engineering Standard) <a class="header-anchor" href="#_1-cost-plus-pricing-the-engineering-standard" aria-label="Permalink to &quot;1. Cost-Plus Pricing (The Engineering Standard)&quot;">​</a></h3><p>You sum direct raw material consumption (including scrap factors), billable craftsman hours, shop overhead allocation (rent, utilities, tooling wear), and add a fixed target profit margin.</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Key Advantage:</strong> Guaranteed cost recovery and complete immunity from selling at a loss during material price spikes.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Limitation:</strong> Ignores perceived artistic value, custom branding, and customer willingness to pay.</div></li></ul><h3 id="_2-market-based-pricing-competitor-benchmarking" tabindex="-1">2. Market-Based Pricing (Competitor Benchmarking) <a class="header-anchor" href="#_2-market-based-pricing-competitor-benchmarking" aria-label="Permalink to &quot;2. Market-Based Pricing (Competitor Benchmarking)&quot;">​</a></h3><p>The artisan reviews trade fairs, online storefronts, and social media of similar studios to set competitive prices.</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Studio Hazard:</strong> Competitors may work from home using old surplus inventory without accounting for their own labor time or depreciation. Blindly copying competitor prices frequently leads straight into hidden insolvency.</div></li></ul><h3 id="_3-value-based-pricing-premium-craft-positioning" tabindex="-1">3. Value-Based Pricing (Premium Craft Positioning) <a class="header-anchor" href="#_3-value-based-pricing-premium-craft-positioning" aria-label="Permalink to &quot;3. Value-Based Pricing (Premium Craft Positioning)&quot;">​</a></h3><p>Pricing is driven by aesthetic desirability, exclusivity, craftsmanship quality, and brand prestige (bespoke packaging, lifetime stitch warranties, custom initials).</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Key Advantage:</strong> Generates maximum gross margins (60% to 80%), creating a robust reinvestment budget for studio growth.</div></li></ul><hr><h2 id="studio-break-even-analysis" tabindex="-1">Studio Break-Even Analysis <a class="header-anchor" href="#studio-break-even-analysis" aria-label="Permalink to &quot;Studio Break-Even Analysis&quot;">​</a></h2><p><strong>The Break-Even Point</strong> represents the minimum sales volume required for studio revenue to precisely equal total fixed and variable operating costs. Profit at this point is zero: the business experiences no net loss, but has not yet generated surplus income.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Financial Model</span><div class="formula-heading">Workshop Break-Even Point (Units)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Break-Even Point (Units)</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Monthly Fixed Overhead</span></span><span class="math-denom"><span class="math-var">Unit Selling Price</span> <span class="math-op">−</span> <span class="math-var">Unit Variable Cost</span></span></span></div></div></div><h4 id="example" tabindex="-1">Example: <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example:&quot;">​</a></h4><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div>Studio rent, heating, and internet: <strong>$1,200 / month</strong>.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div>Retail price of a handcrafted tote bag: <strong>$180</strong>.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div>Variable unit cost (leather, thread, hardware, packaging): <strong>$80</strong>.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div>Contribution margin per tote: 180 − 80 = <strong>$100</strong>.</div></li></ul><div class="formula-hero-card" style="margin:16px 0;"><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Break-Even Units</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num">$1,200</span><span class="math-denom">$100</span></span><span class="math-op">=</span><span class="math-var" style="color:#10b981;">12 bags / month</span></div></div></div><p>The first 12 bags produced each month pay strictly for studio rent and utility bills. True owner profits only begin with the 13th bag sold.</p><div class="tip custom-block"><p class="custom-block-title">Workshop Channel Benchmarks</p><ul><li><strong>Wholesale &amp; Corporate Orders:</strong> Target a healthy gross margin of <strong>20–30%</strong> (25–43% markup). Profitability is driven by batch volume.</li><li><strong>Direct-to-Consumer Retail (Craft Fairs, Studio Store):</strong> Target a margin of <strong>40–55%</strong> (67–122% markup).</li><li><strong>Online Marketplaces (Etsy, Amazon Handmade):</strong> Target a margin of at least <strong>50–60%</strong>, as platform fees, payment processing, and advertising claim up to 25% of final retail revenue.</li></ul></div><hr><h2 id="automated-margin-protection-at-the-workbench" tabindex="-1">Automated Margin Protection at the Workbench <a class="header-anchor" href="#automated-margin-protection-at-the-workbench" aria-label="Permalink to &quot;Automated Margin Protection at the Workbench&quot;">​</a></h2><p>In a busy production workshop, tracking margins manually in paper notebooks or static spreadsheets is risky: material supplier prices fluctuate constantly and product catalogs expand.</p><p>A specialized workshop ERP connects material bills of materials (BOMs), stock inventory, and retail pricing into a single live circuit:</p>',51)),c("div",d,[e(i,{screen:"calculator",interactive:"",lang:"en"})]),a[2]||(a[2]=t('<p>In <strong>OmniCraft ERP</strong>, the recipe costing module immediately highlights true order margin with offcut allowances, direct labor, and overhead absorption, ensuring you never accept an unprofitable order.</p><hr><h2 id="frequently-asked-questions-about-workshop-pricing" tabindex="-1">Frequently Asked Questions About Workshop Pricing <a class="header-anchor" href="#frequently-asked-questions-about-workshop-pricing" aria-label="Permalink to &quot;Frequently Asked Questions About Workshop Pricing&quot;">​</a></h2><div class="craft-faq-accordion"><details class="faq-item"><summary>What is considered a healthy gross margin for craft goods?</summary><div class="faq-content"><p>For custom and small-batch handcrafted goods, a safe retail gross margin is <strong>40–50%</strong> (equivalent to a 67–100% cost markup). If your gross margin dips below 30%, seasonal slowdowns, utility increases, or cutting scrap will immediately push the workshop into a cash deficit.</p></div></details><details class="faq-item"><summary>How do marketplace fees impact retail prices and margins?</summary><div class="faq-content"><p>Marketplaces charge fees as a percentage of the <strong>gross selling price</strong>, not your production cost. If an online platform takes a 20% commission and your markup on cost was only 25% (20% margin), the marketplace absorbs 100% of your gross profit, leaving you with zero net earnings.</p><div class="formula-hero-card" style="margin:12px 0;"><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Marketplace Price</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Net Price Wanted</span></span><span class="math-denom">1 <span class="math-op">−</span> <span class="math-fraction"><span class="math-num"><span class="math-var">Platform Fee %</span></span><span class="math-denom">100</span></span></span></span></div></div></div></div></details><details class="faq-item"><summary>How do I safely calculate maximum promotional discounts?</summary><div class="faq-content"><p>Your maximum discount percentage is bounded by your gross profit margin. Offering a discount equal to your margin leaves you with zero profit. To remain safely profitable, calculate your discount ceiling with:</p><div class="formula-hero-card" style="margin:12px 0;"><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Max Discount %</span><span class="math-op">=</span><span class="math-var">Current Margin %</span><span class="math-op">−</span><span class="math-var">Minimum Retained Margin %</span></div></div></div><p>With a 40% margin and a requirement to retain at least 15% net profit, your promotional discount must never exceed <strong>25%</strong>.</p></div></details><details class="faq-item"><summary>Should business taxes be built into product markup?</summary><div class="faq-content"><p>Yes. Income and sales taxes are collected from gross receipts. Always account for statutory tax rates within your retail price model; otherwise, tax liabilities will be deducted directly from your personal craftsman wage.</p></div></details></div><hr><h2 id="defend-your-studio-margins-systematically" tabindex="-1">Defend Your Studio Margins Systematically <a class="header-anchor" href="#defend-your-studio-margins-systematically" aria-label="Permalink to &quot;Defend Your Studio Margins Systematically&quot;">​</a></h2><p>Sustainable pricing cannot exist upon inaccurate cost foundations: unmeasured offcuts, unpriced owner labor hours, or neglected machine maintenance.</p><div class="cta-grid"><div class="cta-card"><div class="cta-card-badge">Online Tool</div><h3>Cost Calculator</h3><p>Free instant calculation of materials, scrap allowances, hardware, and craftsman billable hours with Excel export.</p><a href="/calculators/product-cost-calculator" class="vp-button alt cta-icon-btn" data-omni-event="sat_pricing_cta_calc"><span>Calculate Unit Cost Online</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div><div class="cta-card featured-cta"><div class="cta-card-badge brand-badge">Desktop Software</div><h3>OmniCraft ERP for Windows</h3><p>Dedicated workshop management: living BOM recipes, moving average cost tracking (MAC), margin protection, and order workbench with zero internet required.</p><a href="/" class="vp-button brand cta-icon-btn" data-omni-event="sat_pricing_cta_home"><span>Explore Desktop ERP</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div></div><hr><h2 id="related-workshop-knowledge-cluster" tabindex="-1">Related Workshop Knowledge Cluster <a class="header-anchor" href="#related-workshop-knowledge-cluster" aria-label="Permalink to &quot;Related Workshop Knowledge Cluster&quot;">​</a></h2><ul><li><a href="/calculators/">OmniCraft Product Cost Calculators Directory</a> — Explore all specialized industry calculators and free Excel estimate templates.</li><li><a href="/articles/cost-calculation-software">Cost Calculation Software: Why Excel and Heavy ERPs Fail Small Studios</a> — A comprehensive review of workshop accounting software.</li><li><a href="/calculators/product-cost-calculator">Universal Product Cost Calculator Online</a> — Calculate batch and unit costs, defect allowances, and export estimates to Excel.</li><li><a href="/calculators/leather-cost-calculator">Leather Goods Cost Calculator</a> — Side hide topography, usable surface area, hardware, and workshop labor rates.</li><li><a href="/calculators/3d-print-cost-calculator">3D Printing Cost Calculator</a> — FDM and SLA resin costs, supports, printer depreciation, and machine hour rates.</li><li><a href="/calculators/cake-cost-calculator">Cake &amp; Pastry Cost Calculator</a> — Ingredient costing, baking shrinkage, decor, and cake packaging for pastry chefs.</li><li><a href="/calculators/candle-cost-calculator">Candle &amp; Soap Making Cost Calculator</a> — Wax density, fragrance oil load percentages, crackling wicks, and jars.</li><li><a href="/calculators/dish-cost-calculator">Recipe &amp; Culinary Cost Calculator</a> — Food cost %, gross vs net shrinkage, and portion condiment accounting.</li><li><a href="/calculators/beauty-cost-calculator">Nail &amp; Beauty Services Cost Calculator</a> — Disposable kits, medical-grade sterilization, and booth rental rates.</li></ul>',11))])}const b=n(p,[["render",m]]);export{y as __pageData,b as default};
